import {tilesetAnimationProfile,validateTilesetAnimations,animationCycle,animationFramePixels,paintAnimationPixel} from './tileset-animation.js';
export function tilesetAnimationWorkshop(api){const $=s=>document.querySelector(s),esc=api.esc;function open(){const session=api.session();if(!session)throw Error('Open the original ROM first.');const reader=session.reader,hash=session.id;tilesetAnimationProfile(reader,hash);const draft=structuredClone(api.project().tilesetAnimations?.[hash]||{});let map=reader.byKey(api.map()?.rom?.key)||reader.maps[0],header,entry,clip=0,frame=0,palette=0,colour=1,timer=null;const stop=()=>{if(timer)clearInterval(timer);timer=null;if($('#tilesetPlay'))$('#tilesetPlay').textContent='▶ Preview';};
 function load(){header=reader.ptr(map.layout.address+16);entry=draft[header]||{mapKey:map.key,keepNative:true,clips:[]};clip=0;frame=0;show();}
 const commitEntry=()=>{entry.mapKey=map.key;if(entry.clips.length)draft[header]=entry;else delete draft[header];};
 function show(){stop();api.modal('Animated tilesets',`<p>Paint loops into primary graphics tiles. A clip affects every map sharing that primary tileset. Secondary native animation remains active. The map editor shows a static frame; use ROM Playtest for native playback.</p><label>Preview map<select id="tilesetMap">${reader.maps.map(m=>`<option value="${esc(m.key)}" ${m.key===map.key?'selected':''}>${esc(m.label||m.key)}</option>`).join('')}</select></label><label><input id="tilesetKeepNative" type="checkbox" ${entry.keepNative?'checked':''}> Keep native primary animation</label><p class="hint-line">With native animation enabled, tiles 416–511 stay reserved for the original flowers and water.</p><label>Clip<select id="tilesetClip">${entry.clips.map((c,i)=>`<option value="${i}" ${i===clip?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><div class="studio-actions"><button id="tilesetAdd" type="button">＋ Add loop</button><button id="tilesetRemove" type="button" ${entry.clips.length?'':'disabled'}>Remove loop</button></div><div id="tilesetClipEditor"></div><p id="tilesetStatus" role="status"></p>`,()=>{stop();commitEntry();validateTilesetAnimations({[hash]:draft});for(const [header,e]of Object.entries(draft))animationCycle(e.clips,e.keepNative&&!!reader.u32(+header+16));api.change(()=>{api.project().tilesetAnimations??={};api.project().tilesetAnimations[hash]=structuredClone(draft);});api.toast('Tileset loops saved. Export or Playtest the edited ROM.');},'Save tileset loops');$('#tilesetMap').onchange=()=>{commitEntry();map=reader.byKey($('#tilesetMap').value);load();};$('#tilesetKeepNative').onchange=()=>{entry.keepNative=$('#tilesetKeepNative').checked;commitEntry();};$('#tilesetClip').onchange=()=>{clip=+$('#tilesetClip').value;frame=0;drawEditor();};$('#tilesetAdd').onclick=()=>{if(entry.clips.length>=8){api.error(Error('Use up to eight loops per primary tileset.'));return;}const graphics=reader.graphics(reader.atlas(map).primary),tile=entry.clips.length*4,tiles=4,base=Array.from(graphics.slice(tile*32,(tile+tiles)*32));while(base.length<tiles*32)base.push(0);entry.clips.push({name:'Loop '+(entry.clips.length+1),tile,tiles,ticks:16,frames:Array.from({length:4},()=>[...base])});clip=entry.clips.length-1;frame=0;commitEntry();show();};$('#tilesetRemove').onclick=()=>{entry.clips.splice(clip,1);clip=Math.max(0,clip-1);frame=0;commitEntry();show();};drawEditor();}
 function drawEditor(){stop();const c=entry.clips[clip],box=$('#tilesetClipEditor');if(!c){box.innerHTML='<p>Add a loop, choose its first 8 × 8 graphics tile and paint its frames.</p>';return;}box.innerHTML=`<label>Name<input id="tilesetName" maxlength="80" value="${esc(c.name)}"></label><div class="field-row"><label>First graphics tile<input id="tilesetFirst" type="number" min="0" max="639" value="${c.tile}"></label><label>Tile count<input id="tilesetCount" type="number" min="1" max="32" value="${c.tiles}"></label><label>Ticks per frame<input id="tilesetTicks" type="number" min="1" max="60" value="${c.ticks}"></label></div><p class="hint-line">Tiles are consecutive 8 × 8 entries. The painting canvas lays them out four across. Changing the tile range reloads the source artwork for every frame.</p><label>Palette<select id="tilesetPalette">${Array.from({length:reader.profile(map).primaryPalettes},(_,i)=>`<option ${i===palette?'selected':''}>${i}</option>`).join('')}</select></label><div class="studio-actions"><button id="tilesetPrev" type="button">Previous frame</button><button id="tilesetNext" type="button">Next frame</button><button id="tilesetPlay" type="button">▶ Preview</button><button id="tilesetFrameAdd" type="button">＋ Copy frame</button><button id="tilesetFrameRemove" type="button">Remove frame</button></div><canvas id="tilesetCanvas" aria-label="Paint animated tiles" style="width:256px;max-width:100%;image-rendering:pixelated;touch-action:none"></canvas><div id="tilesetColours" class="studio-actions"></div>`;
  const draw=()=>{const canvas=$('#tilesetCanvas');if(!canvas)return;const {width,height,pixels}=animationFramePixels(c.frames[frame],c.tiles),primary=reader.atlas(map).primary;canvas.width=width;canvas.height=height;const ctx=canvas.getContext('2d'),im=ctx.createImageData(width,height),colors=Array.from({length:16},(_,i)=>{const n=reader.u16(primary.palettes+(palette*16+i)*2);return[(n&31)*255/31,(n>>5&31)*255/31,(n>>10&31)*255/31];});pixels.forEach((n,i)=>im.data.set([...colors[n],255],i*4));ctx.putImageData(im,0,0);$('#tilesetStatus').textContent='Frame '+(frame+1)+' / '+c.frames.length+' · graphics tiles '+c.tile+'–'+(c.tile+c.tiles-1);$('#tilesetColours').innerHTML=colors.map((rgb,i)=>`<button type="button" data-anim-colour="${i}" aria-label="Colour ${i}" aria-pressed="${i===colour}" style="background:rgb(${rgb.join(',')});min-width:36px;flex:0 0 36px">${i}</button>`).join('');document.querySelectorAll('[data-anim-colour]').forEach(b=>b.onclick=()=>{colour=+b.dataset.animColour;draw();});};
  for(const [id,key]of [['tilesetName','name'],['tilesetTicks','ticks']])$('#'+id).onchange=()=>{c[key]=key==='name'?$('#'+id).value:+$('#'+id).value;commitEntry();};const range=()=>{const tile=+$('#tilesetFirst').value,tiles=+$('#tilesetCount').value;if(!Number.isInteger(tile)||!Number.isInteger(tiles)||tile<0||tiles<1||tiles>32||tile+tiles>reader.profile(map).graphicsCount){api.error(Error('Choose a range inside the primary graphics bank.'));return;}c.tile=tile;c.tiles=tiles;const bytes=Array.from(reader.graphics(reader.atlas(map).primary).slice(tile*32,(tile+tiles)*32));while(bytes.length<tiles*32)bytes.push(0);c.frames=c.frames.map(()=>[...bytes]);commitEntry();draw();};$('#tilesetFirst').onchange=$('#tilesetCount').onchange=range;$('#tilesetPalette').onchange=()=>{palette=+$('#tilesetPalette').value;draw();};$('#tilesetPrev').onclick=()=>{stop();frame=(frame+c.frames.length-1)%c.frames.length;draw();};$('#tilesetNext').onclick=()=>{stop();frame=(frame+1)%c.frames.length;draw();};$('#tilesetFrameAdd').onclick=()=>{stop();if(c.frames.length>=16){api.error(Error('Up to sixteen frames per loop.'));return;}c.frames.splice(frame+1,0,[...c.frames[frame]]);frame++;commitEntry();draw();};$('#tilesetFrameRemove').onclick=()=>{stop();if(c.frames.length<=2){api.error(Error('Keep at least two frames.'));return;}c.frames.splice(frame,1);frame%=c.frames.length;commitEntry();draw();};$('#tilesetPlay').onclick=()=>{if(timer){stop();return;}$('#tilesetPlay').textContent='Stop preview';const canvas=$('#tilesetCanvas');timer=setInterval(()=>{if(!canvas.isConnected){stop();return;}frame=(frame+1)%c.frames.length;draw();},c.ticks*1000/60);};const canvas=$('#tilesetCanvas');let down=false,last=null;const paint=e=>{const r=canvas.getBoundingClientRect(),x=Math.floor((e.clientX-r.left)*canvas.width/r.width),y=Math.floor((e.clientY-r.top)*canvas.height/r.height),from=last||{x,y},steps=Math.max(1,Math.abs(x-from.x),Math.abs(y-from.y));for(let i=0;i<=steps;i++)paintAnimationPixel(c.frames[frame],c.tiles,Math.round(from.x+(x-from.x)*i/steps),Math.round(from.y+(y-from.y)*i/steps),colour);last={x,y};commitEntry();draw();};canvas.onpointerdown=e=>{e.preventDefault();stop();down=true;last=null;canvas.setPointerCapture?.(e.pointerId);paint(e);};canvas.onpointermove=e=>{if(down)paint(e);};canvas.onpointerup=canvas.onpointercancel=()=>{down=false;last=null;};draw();}
 load();}return{open};}
